Given a random line $\ell$ through $p$, the number $k_i$ of disks of ${\cal D}_i$ that are intersected by $\ell$ is at most four, due to disjointness, and
its expectation is $O(|{\cal D}_i|/i)$.
Therefore, by the linearity of expectation,
the expected number of disks of $\cal{D}$ intersected by $\ell$ is bounded by
\begin{align*}
\mathbb{E}\left[\sum_{i \ge 0} k_i\right]
&=   \mathbb{E}\left[\sum_{i\colon i\leq \sqrt{n}} k_i\right] + \mathbb{E}\left[\sum_{i\colon i > \sqrt{n}} k_i\right]\\
&\le 4\sqrt{n} + \sum_{i\colon i > \sqrt{n}} O(|{\cal D}_i|/\sqrt{n})
 =   O(\sqrt{n}) + O(n/\sqrt{n}) = O(\sqrt{n}). 
\tag*{\qed}
\end{align*}

\begin{align*}
\mathbb{E}\left[\sum_{i \ge 0} k_i\right]
&=   \mathbb{E}\left[\sum_{i\colon i\leq \sqrt{n}} k_i\right] + \mathbb{E}\left[\sum_{i\colon i > \sqrt{n}} k_i\right]\\
&\le 4\sqrt{n} + \sum_{i\colon i > \sqrt{n}} O(|{\cal D}_i|/\sqrt{n})
 =   O(\sqrt{n}) + O(n/\sqrt{n}) = O(\sqrt{n}). 
\tag*{\qed}
\end{align*}

\label{lem:joint_unit}
Let $\cal{D}$ be a set of $n$ unit disks in the plane with $m$ intersecting pairs, and let $p$ be any point in the plane.
Then the expected number of disks intersected by a random line through $p$ is $O(\sqrt{(m+n)\log n})$.

\begin{eqnarray*}
\sum_j \sum_i O(\sqrt{m_{ji} + x_{ji}})
 &\leq& O\left(\sqrt{\sum_j \sum_i (m_{ji} + x_{ji})} \sqrt{\sum_j \sum_i 1}\right)\\
 &\leq& O(\sqrt{(m+n)\log n}),
\end{eqnarray*}

\begin{align*}
 m' &< k^2\frac{(1+\ln (2n/k))}{6} 
     < \left(1+\sqrt{\frac{{6m}}{{1+\ln (n/k)}}}\right)^2 \left(\sqrt{\frac{(1+2\ln (n/k))}{6}}\right)^2 \\
    &< \left(\sqrt{\frac{1+2\ln (n/k)}{6}}+\sqrt{2m} \right)^2 <\left(\sqrt{\frac{6n}{6}}+\sqrt{2m} \right)^2 \\
    &<  (\sqrt{m}+\sqrt{2m})^2 =(3+2\sqrt{2}) m.
\end{align*}

\begin{align*}
m' &= \sum_{i=1}^{\ell} \left\lfloor\frac{\gamma_ik}{4\pi i(1+\varepsilon)}\right\rfloor k >  \sum_{i=1}^{\ell} \left( \frac{k}{2\pi i(1+\varepsilon)} -1\right) k 
 >  \frac{k^2}{2\pi + 1} \left(\sum_{i=1}^{\ell} \frac{1}{i}\right)
 - \left(\sum_{i=1}^{\ell} k\right) > \frac{k^2 \ln(l+1)}{2\pi + 1} - n'.
\end{align*}

\begin{align*}
\sum_{i=1}^{\ell} (\frac{\gamma_i k}{i(4\pi +1)} - 1) 
 & >    \frac{2}{4\pi + 1}\left(\sqrt{\frac{6m}{1+\ln \ell }}\right)\left( \sum_{i=1}^{\ell} \frac{1}{i}\right) - \ell\\
 & \geq \frac{2}{4\pi + 1} \left(\sqrt{\frac{6m}{1+\ln \ell}}\right)\ln(\ell +1) - \frac{n' \sqrt{1+\ln \ell}}{\sqrt{6m}}\\
 & \geq \frac{\sqrt{6m (1+\ln \ell )}}{4\pi + 1} - \frac{2m}{9} \sqrt{\frac{1+\ln \ell}{6m}}\\
 & \geq \left(\frac{\sqrt{6}}{4\pi + 1} - \frac{2}{9\sqrt{6}}\right) \sqrt{m(1+\ln \ell)} =  \Omega( \sqrt{m\log (n/\sqrt{m})}).
\tag*{\qed}
\end{align*}

\label{thm:lowerarbitRad}
For any $n\in \mathbb{N}$ there exists a set $\cal{D}$ of $O(n)$ pairwise disjoint disks such that any line $\ell$ for which both halfplanes contain $\Omega(n)$ disks of $\cal{D}$ also 
intersects $\Omega(n)$ disks of $\cal{D}$.
